static z_t15066_t z_t58_parseI64(const z_t58_t* self);
static z_t15066_t z_t58_parseI64(const z_t58_t* self) {
    z_t15066_t out = {0};
    uint64_t i = 0;
    int neg = 0;
    if (self->size == 0) goto empty;
    if (self->data[i] == '+' || self->data[i] == '-') {
        if (self->data[i] == '-') neg = 1;
        i++;
    }
    if (i >= self->size) goto empty;
    uint64_t acc = 0;
    for (; i < self->size; i++) {
        unsigned char c = (unsigned char)self->data[i];
        if (c < '0' || c > '9') goto invalid;
        uint64_t d = (uint64_t)(c - '0');
        if (acc > (UINT64_MAX - d) / 10) goto overflow;
        acc = acc * 10 + d;
    }
    /* range check: fits in i64 */
    uint64_t bound = neg ? (uint64_t)1 << 63 : ((uint64_t)1 << 63) - 1;
    if (acc > bound) goto overflow;
    /* negated in unsigned arithmetic, where 2^63 has a negation too */
    int64_t v = neg ? (int64_t)(0 - acc) : (int64_t)acc;
    out.tag = Z_T15066_TAG_1;
    out.data.a1 = v;
    return out;
empty:
    out.tag = Z_T15066_TAG_0;
    out.data.a0 = Z_T14695_TAG_0;
    return out;
invalid:
    out.tag = Z_T15066_TAG_0;
    out.data.a0 = Z_T14695_TAG_1;
    return out;
overflow:
    out.tag = Z_T15066_TAG_0;
    out.data.a0 = Z_T14695_TAG_2;
    return out;
}


static z_t15118_t z_t58_parseU64(const z_t58_t* self);
