static const z_t6098_t _zag1651 = { { .data = "win_sep", .size = 7 }, { .length = 1, .data = _zag1650 }, { .length = 0, .data = NULL }, { .data = "static int z_win_sep(char c) {\n    return c == '\\\\' || c == '/';\n}", .size = 66 } };
